  let l=i.flags.filter(e=>e.includes(`권장`)||e.includes(`인장`)||e.includes(`불리`)),
      u=s.filter(e=>Number.isFinite(e.margin)),
      f=u.length?Math.min(...u.map(e=>e.margin)):1/0,
      p=u.find(e=>e.margin===f)||null;
