    $GU=x.find(e=>e.id===$P.guideModelId)??$B.calc.selected.guideEval.guide,
    $SR=$DR.screwRpm,$GS=$DR.gear?$DR.gear.gear.size:0,$GF=$DR.movingMassKg*9.80665,
