      $k>1&&$P.blockSpacingMm>0&&$c.push({l:`블록 중심 간격 ${R($P.blockSpacingMm,0)} → ${R($P.blockSpacingMm*$f,0)} mm`,ov:{blockSpacingMm:$P.blockSpacingMm*$f}});
    let $b=$rcPick($B,$K,$c);
    $b&&$add(`${$b.l} 로 확대`,$b,
      `모멘트 하중은 지지 스팬에 반비례해 분담되므로 간격 확대는 부품 교체 없이 정적안전율을 올리는 가장 값싼 대책입니다. 테이블 폭·레일 길이 한계와 장착면 평행도 확보를 함께 확인해야 합니다.`);
