    for(let $j=0;$j<$i;$j++)$c.push({l:`충격 등급 ${pe.find(e=>e.id===$P.shock)?.shortLabel??$P.shock} → ${pe.find(e=>e.id===$o[$j])?.shortLabel??$o[$j]}`,ov:{shock:$o[$j]}});
    let $b=$rcPick($B,$K,$c);
    $b&&$add(`${$b.l} 로 재검토`,$b,`하중계수 fw 가 내려가 계산수명이 늘어납니다. 실제로 정렬·윤활이 양호하고 충격이 없다는 근거가 있을 때만 낮춰야 합니다.`);
    let $c2=[];
    for(let $f of[.8,.6,.5,.4])$P.cyclesPerMin>0&&$c2.push({f:$f,ov:{cyclesPerMin:$P.cyclesPerMin*$f}});
    let $b2=$rcFirst($B,$K,$c2);
    $b2&&$add(`왕복 횟수를 ${R($P.cyclesPerMin,1)} → ${R($P.cyclesPerMin*$b2.f,1)} 회/min 로 완화`,$b2,
      `주행거리 기준 수명(km)은 그대로이고 시간 수명(h)이 늘어납니다. 설비 택트타임 요구와 반드시 함께 결정해야 합니다.`);
