    $best=$srt($safe)[0]||$srt($pass)[0]||$rows.slice().sort((e,t)=>t.min-e.min)[0],
    $E=$best.E,$DR=$E.calc.selected.drive,$GE=$E.calc.selected.guideEval,$set=$E.set,
    $gname=$DR.gear?`KSB${$DR.gear.gear.size}`:$best.r===1?`직결(감속기 없음)`:`형번 미정`,
    $mg=e=>{let $i=$set.items.find(t=>t.key===e);return $i?$rcPct($i.margin):`–`},
    $moBelow=u.filter(e=>e.powerW<$best.mo.powerW).sort((e,t)=>t.powerW-e.powerW)[0],
