    $dBest=$dLower?$rows.filter(e=>e.sc.diameterMm===$dLower&&e.mo.id===$best.mo.id).slice().sort((e,t)=>t.min-e.min)[0]:null,
    $rAlt=$rows.filter(e=>e.mo.id===$best.mo.id&&e.sc.id===$best.sc.id&&e.r!==$best.r).slice().sort((e,t)=>Math.abs(e.r-$best.r)-Math.abs(t.r-$best.r))[0]||null,
    $cp=ue($best.sc.diameterMm,$I.couplingSeries),$why=[];
